package com.oms.order.service;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class TmallPushReaderTest {
    ConfiguredPushReader reader(String url,String user,String password){TmallPushReader.Source s=new TmallPushReader.Source();s.setJdbcUrl(url);s.setUsername(user);s.setPassword(password);s.setRevision(1);return new ConfiguredPushReader(){@Override protected TmallPushReader.Source source(String company,String key){return s;}};}
    Map<String,Object> task(){Map<String,Object> t=new HashMap<>();t.put("start_time","2026-10-01 00:00:00");t.put("end_time","2026-10-02 00:00:00");t.put("page_time","2026-10-01 00:00:00");t.put("page_tid",0);return t;}
    @Test void sameTimestampKeysetPaginationIsShopScopedAndEndExclusive(){String url=System.getenv("ORDER_TEST_URL");Assumptions.assumeTrue(url!=null&&url.contains("/order_workspace_test?"));JdbcTemplate db=new JdbcTemplate(new DriverManagerDataSource(url,"root",System.getenv("INVENTORY_TEST_PASSWORD")));db.execute("CREATE TABLE IF NOT EXISTS jdp_tb_trade(tid BIGINT PRIMARY KEY,status VARCHAR(64),type VARCHAR(64),seller_nick VARCHAR(200),created DATETIME,modified DATETIME,jdp_modified DATETIME,jdp_response MEDIUMTEXT,KEY idx_seller_time(seller_nick,jdp_modified))");db.update("DELETE FROM jdp_tb_trade");for(int i=1;i<=5;i++)db.update("INSERT INTO jdp_tb_trade VALUES (?,'WAIT_SELLER_SEND_GOODS','fixed','seller',NOW(),NOW(),'2026-10-01 01:00:00','{}')",987654321012345670L+i);db.update("INSERT INTO jdp_tb_trade VALUES (1,'','','other',NOW(),NOW(),'2026-10-01 01:00:00','{}'),(2,'','','seller',NOW(),NOW(),'2026-10-02 00:00:00','{}')");ConfiguredPushReader r=reader(url,"root",System.getenv("INVENTORY_TEST_PASSWORD"));try{Map<String,Object> t=task();Set<String> ids=new HashSet<>();for(int i=0;i<3;i++){List<Map<String,Object>> rows=r.read("company","test","seller",t,2);for(Map<String,Object> row:rows)assertTrue(ids.add(OrderValues.text(row,"tid")));Map<String,Object> last=rows.get(rows.size()-1);t.put("page_time",last.get("jdp_modified"));t.put("page_tid",last.get("tid"));}assertEquals(5,ids.size());assertTrue(r.read("company","test","seller",t,2).isEmpty());}finally{r.close();}}
    @Test void configured113SourceAllowsReadOnlyBoundedQuery(){String url=System.getenv("OMS_ORDER_PUSH_113_URL");Assumptions.assumeTrue(url!=null&&!url.isEmpty(),"113 connection is not configured");assertTrue(url.contains("172.16.9.113")&&url.contains("/sys_info?"));ConfiguredPushReader r=reader(url,System.getenv("OMS_ORDER_PUSH_113_USERNAME"),System.getenv("OMS_ORDER_PUSH_113_PASSWORD"));try{assertTrue(r.read("company","test","__OMS_CONNECTIVITY_CHECK_NO_SHOP__",task(),1).isEmpty());}finally{r.close();}}
    @Test void configured100SourceAllowsReadOnlyBoundedQuery(){String url=System.getenv("OMS_ORDER_PUSH_100_URL");Assumptions.assumeTrue(url!=null&&!url.isEmpty(),"100 connection is not configured");assertTrue(url.contains("172.16.9.100")&&url.contains("/sys_info?"));ConfiguredPushReader r=reader(url,System.getenv("OMS_ORDER_PUSH_100_USERNAME"),System.getenv("OMS_ORDER_PUSH_100_PASSWORD"));try{assertTrue(r.read("company","test","__OMS_CONNECTIVITY_CHECK_NO_SHOP__",task(),1).isEmpty());}finally{r.close();}}
}
